item.text:
**Files**
Generated the `.mjs` ESM migration in `/output` with no external dependencies:

- [python_repr.mjs](/output/lib/python_repr.mjs:1)
- [path_parser.mjs](/output/lib/path_parser.mjs:1)
- [deepdiff.mjs](/output/lib/deepdiff.mjs:1)
- [cli.mjs](/output/lib/cli.mjs:1)
- [index.mjs](/output/lib/index.mjs:1)
- [test11.mjs](/output/test11.mjs:1)

The split is: Python-style printing, DeepDiff-style path extraction, minimal DeepDiff behavior for this script, manual `argparse`-compatible CLI parsing, and an entrypoint that wires them together. I verified representative success/error/help cases by diffing against `/workspace/dataset/test11_executable`; output matched, aside from the expected program name in usage/error text (`test11.mjs` instead of `test11_executable`).

**Entry**
```js
import { CliAbort, DeepDiff, extract, parseCommandLine, pythonStr } from './lib/index.mjs';

function printPython(value) {
  console.log(pythonStr(value));
}

function main(argv) {
  const args = parseCommandLine(argv);

  const obj = {
    users: [
      { name: args.a, age: args.b },
      { name: `${args.a}2`, age: args.b + 1n },
    ],
  };

  const r1 = DeepDiff(obj, obj);
  printPython(r1);

  const r2 = extract(obj, "root['users'][0]['name']");
  printPython(r2);

  const r3 = extract(obj, "root['users'][1]['age']");
  printPython(r3);

  const r4 = DeepDiff(obj.users[0], obj.users[1]);
  printPython(r4);

  const r5 = extract(obj, "root['users'][0]");
  printPython(r5);

  const r6 = DeepDiff(obj.users, []);
  printPython(r6);

  const r7 = DeepDiff(obj, { users: [] });
  printPython(r7);

  const r8 = extract(obj, "root['users']");
  printPython(r8);
}

try {
  main(process.argv);
} catch (error) {
  if (error instanceof CliAbort) {
    const stream = error.outputChannel === 'stdout' ? process.stdout : process.stderr;
    stream.write(error.message);
    process.exitCode = error.exitCode;
  } else {
    throw error;
  }
}
```
